function minterExtensionCommitment(KCC20MintExtensionV1 extension): byte[32] {
        byte activeByte = byte(0);
        if (extension.public_mint_active) {
            activeByte = byte(1);
        }
        byte[] payload =
            byte[](byte[1](extension.kind)) +
            byte[](extension.creator) +
            byte[](extension.ticker) +
            byte[](extension.name) +
            OpNum2Bin(extension.display_scale, 8) +
            OpNum2Bin(extension.max_supply, 8) +
            byte[](byte[1](extension.mint_policy)) +
            OpNum2Bin(extension.mint_price_sompi, 8) +
            byte[](extension.treasury) +
            byte[](extension.protocol_fee_recipient) +
            OpNum2Bin(extension.protocol_fee_bps, 8) +
            OpNum2Bin(extension.remaining_supply, 8) +
            byte[](byte[1](activeByte)) +
            byte[](extension.holder_extension_commitment);
        return(blake3(payload));
    }

