function exactMintGrossSompi(KCC20MintExtensionV1 extension, int rawAmount): int {
        require(rawAmount > 0);
        int wholeAmount = rawAmount / extension.display_scale;
        int fractionAmount = rawAmount - wholeAmount * extension.display_scale;
        if (extension.mint_price_sompi > 0) {
            require(wholeAmount <= MAX_INT / extension.mint_price_sompi);
            require(fractionAmount <= MAX_INT / extension.mint_price_sompi);
        }
        int grossWholeSompi = wholeAmount * extension.mint_price_sompi;
        int fractionProduct = fractionAmount * extension.mint_price_sompi;
        int grossFractionSompi = fractionProduct / extension.display_scale;
        require(grossFractionSompi * extension.display_scale == fractionProduct);
        require(grossWholeSompi <= MAX_INT - grossFractionSompi);
        return(grossWholeSompi + grossFractionSompi);
    }

